import{_ as l,l as s,o as e,c as n,v as r,p as o,x as i,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"指纹与 Freivalds","description":"","frontmatter":{"title":"指纹与 Freivalds","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fingerprinting-freivalds.md","filePath":"cs/fingerprinting-freivalds.md","lastUpdated":1789023840000}'),c={name:"cs/fingerprinting-freivalds.md"};function _(f,a,v,m,A,B){const t=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="指纹与-freivalds" tabindex="-1">指纹与 Freivalds <a class="header-anchor" href="#指纹与-freivalds" aria-label="Permalink to &quot;指纹与 Freivalds&quot;">​</a></h1><div class="epigraph"><p>把长对象映射到随机模的短指纹；Freivalds 用随机向量 $O(n^2)$ 检验矩阵乘，错概率 $1/|S|$。</p><footer>—— 据 Freivalds, Fast Probabilistic Algorithms, 1977；Motwani and Raghavan；CLRS 第 5、32 章整理</footer></div><p>上一课<a href="/cs/las-vegas-monte-carlo">Las Vegas 与 Monte Carlo</a>钉了 MC。指纹：串/多项式/矩阵的哈希，碰撞则可能假阳性。缺口是 Freivalds：检验 \\(AB=C\\) 不必 \\(O(n^3)\\) 再乘一遍。不重写 Karatsuba。后课随机游走混合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多项式恒等：随机 \\(x\\) Schwartz–Zippel，\\(d\\) 次多项式在有限 \\(S\\) 上撞根 \\(\\le d/|S|\\)。串匹配 Rabin–Karp 同精神。Freivalds：\\(A,B,C\\) 为 \\(n\\times n\\)，随机 \\(r\\in\\{0,1\\}^n\\)，看 \\(A(Br)\\stackrel{?}{=}Cr\\)，三次矩阵–向量 \\(O(n^2)\\)。错当 \\(AB\\neq C\\) 仍相等，概率 \\(\\le 1/2\\)（域更大则更小）。重复 \\(k\\) 次。</p><p>缺口是检验不是计算乘积。</p><h3 id="不是密码学碰撞抗性" tabindex="-1">不是密码学碰撞抗性 <a class="header-anchor" href="#不是密码学碰撞抗性" aria-label="Permalink to &quot;不是密码学碰撞抗性&quot;">​</a></h3><p>这里是算法 MC，模随机素数。对手看到随机数之前选输入。自适应对手另论。</p><p><span class="marginnote">Freivalds 1977。Schwartz–Zippel。Rabin–Karp。后课混合时间是马尔可夫，不是指纹。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选随机点或向量，模大素数。失败则「可能不等/再试」。要 Las Vegas 乘仍用确定乘。</p>',11)),(e(),o(h,null,{default:i(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%A4%9A%E9%A1%B9%E5%BC%8F%20%2F%20%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20FP%5B%22%E9%9A%8F%E6%9C%BA%E6%8C%87%E7%BA%B9%22%5D%0A%20%20FP%20--%3E%20EQ%5B%22%E7%9B%B8%E7%AD%89%EF%BC%9FMC%22%5D%0A%20%20AB%5B%22AB%20vs%20C%22%5D%20--%3E%20FR%5B%22Freivalds%20A(Br)%3DCr%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>串：滚动哈希注意溢出当模。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>线性：\\((AB-C)r=0\\) 对随机 \\(r\\) 当 \\(AB-C\\neq 0\\) 很少。多项式：\\(P(x)=0\\) 根少。与 NTT：NTT 精确卷积；指纹是概率检验。与哈希表：指纹可当键，有碰撞。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写密码学哈希函数。不写 PCP 指纹。后课默认：\\(O(n^2)\\) 检验矩阵乘用 Freivalds。下一课随机游走与混合。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指纹把相等检验变成 MC。</li><li>Freivalds \\(O(n^2)\\) 检验乘。</li><li>Schwartz–Zippel 管多项式。</li><li>出处：Freivalds, 1977；Motwani–Raghavan。</li></ul>',7))])}const F=l(c,[["render",_]]);export{C as __pageData,F as default};
